// Simulates what an installation's meter would report, so the seed script and the backfill produce
// the same realistic pattern: zero at night, a bell-shaped curve peaking around midday, occasional cloud dips.

const SLOT_MS = 15 * 60 * 1000; // meters report every 15 minutes
const COLOMBO_UTC_OFFSET_HOURS = 5.5; // Sri Lanka is UTC+05:30 all year (no daylight saving)
const SUNRISE_HOUR = 6; // 06:00 local time
const SUNSET_HOUR = 18.5; // 18:30 local time

// The columns filled when inserting a reading (reading_id is generated by the database).
const READING_COLUMNS = ['installation_id', 'timestamp', 'received_at', 'power_kw', 'energy_kwh', 'voltage_v'];

// A linear congruential generator: next = (1664525 * current + 1013904223) mod 2^32.
// Not for security - it gives repeatable "randomness": the same seed always produces the same sequence,
// which is what makes the seed data identical every time it is generated.
function createRng(seed) {
  let state = seed >>> 0;
  return function next() {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296; // scale to a number from 0 up to (not including) 1
  };
}

// The latest 15-minute boundary at or before `date` (10:07 -> 10:00).
function floorToSlot(date) {
  return new Date(Math.floor(date.getTime() / SLOT_MS) * SLOT_MS);
}

// How much of its full output a panel can produce at this moment, from 0 to 1, using Colombo local time.
// sin^2 across the daylight hours gives a bell shape: 0 at sunrise, 1 at midday (about 12:15), 0 at sunset.
function daylightFactor(timestamp) {
  const utcHours = timestamp.getUTCHours() + timestamp.getUTCMinutes() / 60;
  const localHours = (utcHours + COLOMBO_UTC_OFFSET_HOURS) % 24;
  if (localHours <= SUNRISE_HOUR || localHours >= SUNSET_HOUR) return 0;
  return Math.sin((Math.PI * (localHours - SUNRISE_HOUR)) / (SUNSET_HOUR - SUNRISE_HOUR)) ** 2;
}

function round(value, decimals) {
  const factor = 10 ** decimals;
  return Math.round(value * factor) / factor;
}

// Builds one reading for one 15-minute slot. energy_kwh is the meter's running total and never goes down,
// so the caller passes in the previous total and gets the new total back inside the reading.
function simulateReading(installation, timestamp, previousEnergyKwh, rng) {
  const cloudFactor = rng() < 0.2 ? 0.3 + rng() * 0.4 : 0.9 + rng() * 0.1; // about 1 slot in 5 is under cloud
  // 0.8: real systems lose about a fifth of their rated output (heat, dust, inverter losses).
  const powerKw = round(installation.capacity_kw * 0.8 * daylightFactor(timestamp) * cloudFactor, 3);

  return {
    installation_id: installation.installation_id,
    timestamp,
    received_at: new Date(timestamp.getTime() + 2000 + Math.floor(rng() * 20000)), // arrives 2-22 s after measuring
    power_kw: powerKw,
    energy_kwh: round(previousEnergyKwh + powerKw * 0.25, 3), // kW x 0.25 h = kWh generated in this slot
    voltage_v: round(230 + (rng() - 0.5) * 6, 1), // grid voltage, 227-233 V
  };
}

module.exports = { SLOT_MS, READING_COLUMNS, createRng, floorToSlot, simulateReading };
